sealed class EventBody implements Wire {
  const EventBody();

  static EventBody fromJson(Object? json) {
    final m = asMap(json);
    switch (m['type']) {
      case 'user':
        return EventBodyUser.fromJson(m);
      case 'rewind':
        return EventBodyRewind.fromJson(m);
      case 'textDelta':
        return EventBodyTextDelta.fromJson(m);
      case 'assistantText':
        return EventBodyAssistantText.fromJson(m);
      case 'toolCall':
        return EventBodyToolCall.fromJson(m);
      case 'toolResult':
        return EventBodyToolResult.fromJson(m);
      case 'interrupted':
        return EventBodyInterrupted.fromJson(m);
      case 'approval':
        return EventBodyApproval.fromJson(m);
      case 'approvalResolved':
        return EventBodyApprovalResolved.fromJson(m);
      case 'checkpoint':
        return EventBodyCheckpoint.fromJson(m);
      case 'restored':
        return EventBodyRestored.fromJson(m);
      case 'compaction':
        return EventBodyCompaction.fromJson(m);
      case 'usage':
        return EventBodyUsage.fromJson(m);
      case 'turnEnd':
        return EventBodyTurnEnd.fromJson(m);
      case 'error':
        return EventBodyError.fromJson(m);
    }
    throw FormatException('EventBody: unknown type ${m['type']}');
  }

  @override
  Map<String, Object?> toJson();
}

