    final m = asMap(json);
    return ProviderConfig(
      apiKeyEnv: m['apiKeyEnv'] == null ? null : m['apiKeyEnv'] as String,
      baseUrl: m['baseUrl'] == null ? null : m['baseUrl'] as String,
