      command: m['command'] == null ? null : [for (final x in asList(m['command'])) x as String],
      env: m['env'] == null
          ? null
          : {for (final kv in asMap(m['env']).entries) kv.key: kv.value as String},
      id: m['id'] as String,
      kind: ProviderKind.fromJson(m['kind']),
      models: m['models'] == null ? null : [for (final x in asList(m['models'])) x as String],
      name: m['name'] as String,
    );
  }

  @override
