    if (apiKeyEnv != null) 'apiKeyEnv': apiKeyEnv!,
    if (baseUrl != null) 'baseUrl': baseUrl!,
    if (capabilities != null) 'capabilities': capabilities!.toJson(),
    if (command != null) 'command': command!,
