sealed class Sha256Source implements Wire {
  const Sha256Source();

  static Sha256Source fromJson(Object? json) {
    final m = asMap(json);
    switch (m['kind']) {
      case 'digest':
        return Sha256SourceDigest.fromJson(m);
      case 'url':
        return Sha256SourceUrl.fromJson(m);
    }
    throw FormatException('Sha256Source: unknown kind ${m['kind']}');
  }

  @override
  Map<String, Object?> toJson();
}

