/// Opaque identifier of an open workspace, minted by `workspace/open`.
typedef WorkspaceId = String;

/// A path inside a workspace: relative to the workspace root, `/`-separated,
/// UTF-8, with no `.`/`..` segments, no leading `/`, and no trailing `/`.
/// The workspace root itself is the empty string.
///
/// Clients never send absolute host paths except in `workspace/open`. The
/// daemon rejects any `WorkspacePath` that fails these rules with
/// [`ErrorKind::InvalidParams`] and any that resolves (through symlinks)
/// outside the root with [`ErrorKind::PermissionDenied`].
typedef WorkspacePath = String;

final class WorkspaceRef implements Wire {
  const WorkspaceRef({required this.workspaceId});

  final WorkspaceId workspaceId;

  static WorkspaceRef fromJson(Object? json) {
    final m = asMap(json);
    return WorkspaceRef(workspaceId: m['workspaceId'] as String);
  }

  @override
  Map<String, Object?> toJson() => {'workspaceId': workspaceId};
}

final class WriteFileParams implements Wire {
  const WriteFileParams({
    this.expectedVersion,
    this.overwrite,
    required this.path,
    required this.text,
    required this.workspaceId,
  });

  /// Version the client last read. If set, the write is refused with
  /// `conflict` unless the file on disk still has this version. Omit to
  /// create a new file (fails with `conflict` if the file exists) —
  /// set [`WriteFileParams::overwrite`] to bypass both checks.
  final FileVersion? expectedVersion;

  /// Write unconditionally. Used for "overwrite anyway" after a conflict.
  final bool? overwrite;
  final WorkspacePath path;
  final String text;
  final WorkspaceId workspaceId;

  static WriteFileParams fromJson(Object? json) {
    final m = asMap(json);
    return WriteFileParams(
      expectedVersion: m['expectedVersion'] == null ? null : m['expectedVersion'] as String,
      overwrite: m['overwrite'] == null ? null : m['overwrite'] as bool,
      path: m['path'] as String,
      text: m['text'] as String,
      workspaceId: m['workspaceId'] as String,
    );
  }

  @override
  Map<String, Object?> toJson() => {
    if (expectedVersion != null) 'expectedVersion': expectedVersion!,
    if (overwrite != null) 'overwrite': overwrite!,
    'path': path,
    'text': text,
    'workspaceId': workspaceId,
  };
}

